import {renderHome,renderCourse,card} from './render.js?v=20261021seo';
import {initTracking,trackRegistrationLead} from './tracking.js?v=20261021b';
initTracking();
import {EARLY_BIRD_END,earlyBirdDiscount,campTotal} from './pricing.js';
import {config} from './config.js';
import {refundHtml} from './refund.js';
const $=s=>document.querySelector(s),money=n=>'NT$ '+n.toLocaleString('zh-TW'),line='https://lin.ee/NTY6jV8';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let camps=[];const main=$('#main');
const date=s=>s.slice(5).replace('-','/');
const priceMarkup=base=>`<span data-base-price="${base}">${earlyBirdDiscount()?`<del class="original-price">${money(base)}</del> <span class="early-price">${money(campTotal(base))}<small> 早鳥價</small></span>`:money(base)}</span>`;
const enroll=(c,p='')=>`register.html?camp=${c.id}${p?'&plan='+p:''}`;
function home(){main.innerHTML=renderHome(camps);
const controls=[$('#gradeFilter'),$('#dateFilter'),$('#abilityFilter')];const saved=new URLSearchParams(location.search);controls[0].value=saved.get('grade')||'';controls[1].value=saved.get('date')||'';controls[2].checked=saved.get('ability')==='1';
function filter(){const [g,d,a]=controls;const list=camps.filter(c=>(!g.value||c.grades.includes(+g.value)||(c.id==='rc'&&a.checked))&&(!d.value||c.id===d.value));$('#count').textContent=`找到 ${list.length} 個適合的營隊`;const q=new URLSearchParams(location.search);for(const key of ['grade','date','ability'])q.delete(key);if(g.value)q.set('grade',g.value);if(d.value)q.set('date',d.value);if(a.checked)q.set('ability','1');history.replaceState(null,'',location.pathname+(q.size?'?'+q:'')+location.hash);try{sessionStorage.setItem('campFilter',q.toString())}catch{}$('#cards').innerHTML=list.length?list.map(c=>card(c)).join(''):'<div class="empty"><h3>目前沒有符合全部條件的營隊</h3><p>試著放寬日期或清除條件；若孩子已有組裝能力，也可勾選 Technic 能力條件。</p><a href="https://lin.ee/NTY6jV8">請老師協助選營 ↗</a></div>'}controls.forEach(c=>c.addEventListener('change',filter));$('#clear').onclick=()=>{controls[0].value='';controls[1].value='';controls[2].checked=false;filter()};filter();}
function course(c){let back="index.html#camps";try{const q=sessionStorage.getItem("campFilter");if(q)back="index.html?"+q+"#camps"}catch{}main.innerHTML=renderCourse(c,back);}
function registration(){const params=new URLSearchParams(location.search),cid=params.get('camp'),pid=params.get('plan');let selected=camps.find(c=>c.id===cid);const invalid=(cid&&!selected)||(pid&&(!selected||!selected.plans.some(p=>p.id===pid)));if(invalid)selected=null;
main.innerHTML=`<div class="wrap"><div class="breadcrumb"><a href="index.html#camps">← 返回營隊總覽</a></div><div class="eyebrow">LET'S MAKE SOMETHING GREAT</div><h1 style="font-size:40px">為孩子，安排一場探索。</h1><p>每次填寫一位孩子、一個營隊。請先核對日期、方案與費用。</p>${invalid?'<p class="notice" role="alert">連結中的營隊或方案無效，請重新選擇。</p>':''}<div class="form-layout"><aside><div class="panel summary-box"><h2>你的營隊選擇</h2><div id="summary">請先選擇營隊。</div><p class="hint">送出資料後，仍需透過 LINE 確認名額與繳費。</p></div></aside><form id="registration"><div class="notice">${config.registrationOpen?'收件不等於完成報名，名額與付款由老師確認。':'報名尚未開放。你可以先查看與試填，資料不會送出或保存在此裝置。請透過 LINE 洽詢。'}</div><fieldset><legend>01　選擇營隊與方案</legend><label for="camp">營隊 *</label><select name="camp" id="camp" required><option value="">請選擇營隊</option>${camps.map(c=>`<option value="${c.id}">${c.name}｜${c.dateLabel}</option>`).join('')}</select><div class="field" style="margin-top:18px"><label for="plan">方案 *</label><select id="plan" name="plan" required><option value="">請先選營隊</option></select></div><label>預約早托（選填）</label><p class="hint">08:00–08:30，每個日期加 100 元；08:30 後一般到班免早托費。</p><div id="early" class="dates"></div></fieldset><fieldset><legend>02　孩子的資料</legend><div class="field-grid">${field('child','孩子姓名 *','text',true)}<div class="field"><label for="grade">年級 *</label><select id="grade" name="grade" required><option value="">請選擇</option>${[1,2,3,4,5,6].map(n=>`<option value="${n}">國小 ${n} 年級</option>`).join('')}<option value="7">國中以上</option><option value="0">其他／尚未入小學</option></select></div></div>${field('school','學校（選填）')}<label for="experience">相關經驗</label><select id="experience" name="experience"><option value="none">第一次接觸</option><option value="some">曾接觸組裝或程式</option></select><label id="abilityRow" class="check" hidden><input type="checkbox" name="ability">孩子能自行完成標示 8+ 的 LEGO Technic 組裝（未達三年級須符合）</label><p id="eligibility" class="error" aria-live="polite"></p></fieldset><fieldset><legend>03　家長與緊急聯絡</legend><div class="field-grid">${field('parent','家長稱呼 *','text',true)}${field('phone','手機 *','tel',true)}${field('email','Email *','email',true)}${field('emergencyName','緊急聯絡人 *','text',true)}${field('emergencyPhone','緊急聯絡電話 *','tel',true)}</div><p class="hint">Email 用於寄送收件通知，請核對拼字；電話用於報名及緊急聯繫。</p></fieldset><fieldset><legend>04　其他需求與確認</legend>${field('referral','推薦人（選填）')}<p class="hint">可填「某某孩子的媽媽／爸爸」。</p><label for="diet">特殊飲食／過敏需求（選填）</label><textarea id="diet" name="diet" maxlength="500"></textarea><label for="notes">需協助事項（選填）</label><textarea id="notes" name="notes" maxlength="500"></textarea><details><summary>個人資料使用說明</summary><p>資料由創意方塊機器人教室用於本次營隊報名、聯繫、接送及緊急處理，保存於非公開管理表，僅授權人員處理。你可透過 LINE 要求查詢、更正或刪除；不提供必要資料將無法受理報名。不包含行銷或照片使用授權。保存期限與完整告知事項將於開放前補齊。</p></details><details open><summary>營隊退費辦法（報名前請閱讀）</summary>${refundHtml}</details><label class="check"><input name="privacy" type="checkbox" required>我已閱讀個人資料使用說明，並同意用於本次報名與聯繫。*</label><label class="check"><input name="rules" type="checkbox" required>我已閱讀並同意上述營隊退費辦法；了解收件不代表保留名額，須完成繳費與教室確認。*</label><label id="outdoorRow" class="check" hidden><input name="outdoor" type="checkbox">我了解遙控車營安排戶外活動；教室提供地點、交通與雨備後，須另行取得我的同意。</label></fieldset><p id="formStatus" class="status error" role="alert"></p><button type="submit" id="submit">送出報名資料</button> <a href="${line}">LINE 洽詢 ↗</a></form></div></div>`;
const form=$('#registration');if(selected)$('#camp').value=selected.id;
function update(reset=true){const c=camps.find(c=>c.id===$('#camp').value);if(reset){$('#plan').innerHTML=c?'<option value="">請選擇方案</option>'+c.plans.map(p=>`<option value="${p.id}">${p.name}｜${money(campTotal(p.price))}${earlyBirdDiscount()?'（早鳥價）':''}</option>`).join(''):'<option value="">請先選營隊</option>';if(c?.plans.length===1)$('#plan').value=c.plans[0].id;$('#early').innerHTML=c?c.dates.map(d=>`<label class="check"><input type="checkbox" name="early" value="${d}">${date(d)}</label>`).join(''):'';form.elements.outdoor.checked=false;form.elements.ability.checked=false;}$('#abilityRow').hidden=c?.id!=='rc';$('#outdoorRow').hidden=c?.id!=='rc';form.elements.outdoor.required=c?.id==='rc';const p=c?.plans.find(p=>p.id===$('#plan').value),early=form.querySelectorAll('[name=early]:checked').length;$('#summary').innerHTML=c?`<h3>${c.name}</h3><p>2027/${c.dateLabel} · ${c.dates.length} 天<br>09:00–16:00<br>${c.audience}</p><p>${p?p.name:'請選擇方案'}</p>${p?`<p>原方案費用：${money(p.price)}<br><span id="earlyDiscount">早鳥優惠折抵：−${money(earlyBirdDiscount())}</span></p>`:''}<p>早托 ${early} 天：${money(early*100)}</p><div class="total">${p?money(campTotal(p.price,early)):'—'}</div>${p?priceCountdown():''}<p class="hint">含午餐，晚托另計。</p>`:'請先選擇營隊。';const g=Number(form.elements.grade.value);const ok=!c||!form.elements.grade.value||c.grades.includes(g)||(c.id==='rc'&&form.elements.ability.checked);$('#eligibility').textContent=ok?'':'目前不符合所選營隊資格，請調整選擇或聯絡老師。';form.elements.grade.setCustomValidity(ok?'':'請確認孩子符合營隊參加條件。');}
document.addEventListener('early-bird-ended',()=>{if(!document.contains(form))return;const c=camps.find(c=>c.id===$('#camp').value);if(c)for(const o of $('#plan').options){const p=c.plans.find(p=>p.id===o.value);if(p)o.textContent=p.name+'｜'+money(p.price)}update(false)});$('#camp').onchange=()=>update();form.addEventListener('change',e=>{if(e.target.id!=='camp')update(false)});update();if(selected&&pid&&!invalid){$('#plan').value=pid;update(false)}$('#submit').disabled=!config.registrationOpen||!config.endpoint;
let requestId=null,pendingPayload=null;
form.onsubmit=async e=>{e.preventDefault();if(!config.registrationOpen||!config.endpoint)return;update(false);if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));values.early=[...form.querySelectorAll('[name=early]:checked')].map(x=>x.value);for(const k of ['privacy','rules','outdoor','ability'])values[k]=form.elements[k].checked;values.consentVersion=config.consentVersion;const signature=JSON.stringify(values);if(pendingPayload&&pendingPayload!==signature){$('#formStatus').textContent='上一筆送出結果尚未確認。請恢復原資料重試，或透過 LINE 請老師查核，避免重複登記。';return}requestId??=crypto.randomUUID();pendingPayload=signature;$('#submit').disabled=true;$('#formStatus').textContent='正在送出，請稍候…';const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),20000);try{const res=await fetch(config.endpoint,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({...values,requestId}),signal:ctrl.signal});const data=await res.json();if(!res.ok||!data.ok){if(data.saved===false){pendingPayload=null;requestId=null}throw new Error(data.message||'尚未確認收件，請稍後重試。')}if(!data.registrationId)throw new Error('回應缺少收件編號，請聯絡教室核對。');trackRegistrationLead(data,requestId);const message=`老師您好，我已填寫 2027 冬令營報名表，請協助確認報名狀態與繳費方式。\n報名編號：${data.registrationId}\n孩子姓名：${values.child}\n營隊：${data.campName}\n日期：${data.dateLabel}\n方案：${data.planName}\n謝謝老師！`;main.innerHTML=`<section class="success panel"><div class="eyebrow">RECEIVED · 下一步，聯絡老師</div><h1 style="font-size:36px" tabindex="-1">報名資料已收到</h1><p>報名編號：<strong>${esc(data.registrationId)}</strong><br>${esc(data.campName)} · ${esc(data.dateLabel)}<br>${esc(data.planName)} · ${money(data.total)}</p><div class="notice">還差一步：請主動傳送 LINE 訊息。只加入好友，老師無法主動與你對話；請複製下方文字，加入 LINE 後貼上並按「傳送」。老師收到訊息後，才能核對孩子的報名狀態。名額仍須經繳費與教室確認。</div><label for="lineMessage">① 複製下方報名確認訊息</label><textarea id="lineMessage" rows="9" readonly style="min-height:230px;line-height:1.8">${esc(message)}</textarea><button id="copy" class="secondary">複製報名確認訊息</button><p id="copyStatus" aria-live="polite"></p><p><a class="button line" href="${line}" target="_blank" rel="noopener">② 加入／開啟教室 LINE ↗</a></p><p><strong>③ 在對話中貼上訊息，並按「傳送」。</strong></p><p class="hint">已是好友可直接開啟對話。複製或加入好友不會自動傳送訊息，請務必完成第 ③ 步。</p></section>`;$('h1').focus();$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(message);$('#copyStatus').textContent='已複製！請開啟教室 LINE，貼上後務必按「傳送」。'}catch{$('#lineMessage').select();$('#copyStatus').textContent='請長按或手動複製上方訊息。'}};}catch(err){$('#formStatus').textContent=err.name==='AbortError'?'連線逾時，收件結果尚未確認。資料已保留在本頁；請勿關閉，可用相同資料重試，或聯絡老師查核。':err.message;$('#submit').disabled=false;}finally{clearTimeout(timer)}};
}
function field(name,label,type='text',required=false){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" ${required?'required':''} maxlength="${type==='email'?120:80}" ${type==='tel'?'pattern="[0-9+() -]{8,20}" inputmode="tel"':''}></div>`}
try{const r=await fetch('camps.json?v=20261021seo');if(!r.ok)throw Error();camps=await r.json();const view=document.body.dataset.view;if(view==='home')home();else if(view==='course')course(camps.find(c=>c.id===document.body.dataset.camp));else registration();}catch{if(document.body.dataset.view==='register'||!main.querySelector('h1'))main.innerHTML='<div class="wrap section"><h1>營隊資訊暫時無法載入</h1><p>請重新整理頁面，或透過 LINE 聯絡教室。</p><a href="https://lin.ee/NTY6jV8">LINE 聯絡教室</a></div>'}


let earlyWasActive=earlyBirdDiscount()>0;
function countdownText(){const left=Math.max(0,EARLY_BIRD_END-Date.now());if(!left)return '早鳥優惠已截止';const sec=Math.floor(left/1000),d=Math.floor(sec/86400),h=Math.floor(sec%86400/3600),m=Math.floor(sec%3600/60),s=sec%60;return `優惠倒數 ${d} 天 ${String(h).padStart(2,'0')} 時 ${String(m).padStart(2,'0')} 分 ${String(s).padStart(2,'0')} 秒`;}
function priceCountdown(){return `<div class="price-countdown"><span data-price-countdown role="timer" aria-label="早鳥優惠剩餘時間">${countdownText()}</span><small ${earlyBirdDiscount()?'':'hidden'}>11/1 23:59 截止・每筆現折 NT$ 500</small></div>`;}
function tickEarlyBird(){const active=earlyBirdDiscount()>0,banner=$('#earlyBird'),clock=$('#earlyClock');if(clock)clock.textContent=countdownText();if(!active){if(banner)banner.innerHTML='<div class="wrap"><strong>早鳥優惠已截止，目前以原價報名。</strong></div>';if(earlyWasActive){earlyWasActive=false;document.querySelectorAll('[data-base-price]').forEach(el=>el.textContent=money(Number(el.dataset.basePrice)));document.dispatchEvent(new Event('early-bird-ended'));}}document.querySelectorAll('[data-price-countdown]').forEach(el=>{el.textContent=countdownText();el.nextElementSibling.hidden=!active;});}

tickEarlyBird();setInterval(tickEarlyBird,1000);document.addEventListener('visibilitychange',tickEarlyBird);
